function seedFirestoreData(force) {
  if (!force && localStorage.getItem("coffeemarket_seeded")) {
    console.log("Already seeded");
    return Promise.resolve();
  }
  var promises = SEED_PRODUCTS.map(function(product) {
    return db.collection("products").doc(product.id).set(product);
  });
  return Promise.all(promises).then(function() {
    localStorage.setItem("coffeemarket_seeded", "true");
    console.log("Seeded " + SEED_PRODUCTS.length + " products");
  });
}

window.seedFirestoreData = seedFirestoreData;